"""Admission test and schedule compiler for recurring nonuniform allgather.

Model (see PROTOCOL.md): participants may replicate the chunks they receive,
ordinary forwarding vertices may not.  One period provides c_l = p * b_l chunk
slots on each directed physical link.  A proposal is admissible exactly when no
vertex set S that contains some but not all participants satisfies

    sum(c_l for links crossing S) < sum(r_v for participants v in S)

(Edmonds style arborescence packing / deficient cut duality).  When the
inequality fails we emit the deficient set as a negative witness, otherwise we
compile weighted logical out-trees plus compressed physical unicast routes.
"""

from fcflow import FlowGraph

INF = 1 << 200


# --------------------------------------------------------------------------
# cut certificates
# --------------------------------------------------------------------------
def deficient_cut(n, arcs, parts, rdem, total):
    """Return a vertex list S violating the cut condition, or None.

    arcs: dict (u,v)->capacity (directed).  parts: iterable of participants.
    rdem: dict participant->demand.  total: sum of demands.
    """
    parts = sorted(parts)
    for b in parts:
        g = FlowGraph(n + 2)
        sig = n
        tau = n + 1
        for (u, v), c in arcs.items():
            if c > 0:
                g.add_arc(u, v, c)
        for w in parts:
            if rdem[w] > 0:
                g.add_arc(sig, w, rdem[w])
        g.add_arc(b, tau, INF)
        val, reach = g.maxflow(sig, tau, want_cut=True)
        if val < total:
            S = [i for i in range(n) if reach[i]]
            return S
    return None


def cut_value(arcs, S):
    inS = set(S)
    tot = 0
    for (u, v), c in arcs.items():
        if u in inS and v not in inS:
            tot += c
    return tot


# --------------------------------------------------------------------------
# phase 1: eliminate ordinary forwarding vertices by reserving paths
# --------------------------------------------------------------------------
class SwitchEliminator:
    def __init__(self, n, cap, parts, rdem, total):
        self.n = n
        self.cap = cap                 # dict (u,v) -> int, mutated
        self.parts = sorted(parts)
        self.pset = set(parts)
        self.rdem = rdem
        self.total = total
        self.edge_map = {}             # (u,t) -> {w: amount}
        self.src = n                   # SOURCE node id
        self.fg = FlowGraph(n + 1)
        self.arc_of = {}               # (u,v) -> fg arc id
        for (u, v), c in cap.items():
            if c > 0:
                self.arc_of[(u, v)] = self.fg.add_arc(u, v, c)
        self.src_arc = {}
        for b in self.parts:
            self.src_arc[b] = self.fg.add_arc(self.src, b, rdem[b])
        self.inf_cache = {}            # (u,v) -> fg arc id (capacity 0)

    def _arc(self, u, v):
        a = self.arc_of.get((u, v))
        if a is None:
            a = self.fg.add_arc(u, v, 0)
            self.arc_of[(u, v)] = a
        return a

    def _inf_arc(self, u, v):
        a = self.inf_cache.get((u, v))
        if a is None:
            a = self.fg.add_arc(u, v, 0)
            self.inf_cache[(u, v)] = a
        return a

    def _set_cap(self, u, v, c):
        a = self._arc(u, v)
        self.fg.set_cap(a, c)

    def _get_cap(self, u, v):
        return self.cap.get((u, v), 0)

    # min over S: u in S, w not in S, S excludes some participant, of slack(S)
    def _slack_src_u_sink_w(self, u, w, excluded_candidates):
        fg = self.fg
        a_us = self._inf_arc(u, self.src)
        fg.set_cap(a_us, INF)
        best = None
        try:
            for v in excluded_candidates:
                a_vw = self._inf_arc(v, w)
                fg.set_cap(a_vw, INF)
                val = fg.maxflow(u, w)
                fg.set_cap(a_vw, 0)
                val -= self.total
                if best is None or val < best:
                    best = val
                if best <= 0:
                    break
        finally:
            fg.set_cap(a_us, 0)
        return best

    def _slack_src_w_sink_t(self, w, t, forced_out, loop_nodes):
        fg = self.fg
        a_ws = self._inf_arc(w, self.src)
        fg.set_cap(a_ws, INF)
        best = None
        keep = []
        try:
            for v in forced_out:
                a = self._inf_arc(v, t)
                fg.set_cap(a, INF)
                keep.append(a)
            if loop_nodes is None:
                val = fg.maxflow(w, t) - self.total
                best = val
            else:
                for v in loop_nodes:
                    a = self._inf_arc(v, t)
                    fg.set_cap(a, INF)
                    val = fg.maxflow(w, t) - self.total
                    fg.set_cap(a, 0)
                    if best is None or val < best:
                        best = val
                    if best <= 0:
                        break
        finally:
            fg.set_cap(a_ws, 0)
            for a in keep:
                fg.set_cap(a, 0)
        return best

    def run(self):
        n = self.n
        cap = self.cap
        switches = sorted(set(range(n)) - self.pset)
        parts = self.parts
        for w in switches:
            preds = sorted(u for u in range(n) if u != w and cap.get((u, w), 0) > 0)
            for u in preds:
                if cap.get((u, w), 0) <= 0:
                    continue
                succs = sorted(t for t in range(n) if t != w and cap.get((w, t), 0) > 0)
                for t in succs:
                    cuw = cap.get((u, w), 0)
                    if cuw <= 0:
                        break
                    cwt = cap.get((w, t), 0)
                    if cwt <= 0:
                        continue
                    if u == t:
                        continue
                    M = cuw if cuw < cwt else cwt
                    # test 1: cuts containing u, excluding w
                    cand = [v for v in parts if v != u and v != t]
                    if not cand:
                        cand = [v for v in parts if v != u]
                    if cand:
                        s1 = self._slack_src_u_sink_w(u, w, cand)
                        if s1 is None:
                            s1 = 0
                        if s1 < M:
                            M = s1
                    if M <= 0:
                        continue
                    # test 2: cuts containing w, excluding t (and u)
                    forced = []
                    if u in self.pset:
                        forced = []
                        loop = None
                    elif t in self.pset:
                        forced = [u]
                        loop = None
                    else:
                        forced = [u]
                        loop = [v for v in parts]
                    s2 = self._slack_src_w_sink_t(w, t, forced, loop)
                    if s2 is None:
                        s2 = 0
                    if s2 < M:
                        M = s2
                    if M <= 0:
                        continue
                    # reserve
                    cap[(u, w)] = cuw - M
                    cap[(w, t)] = cwt - M
                    self._set_cap(u, w, cap[(u, w)])
                    self._set_cap(w, t, cap[(w, t)])
                    cap[(u, t)] = cap.get((u, t), 0) + M
                    self._set_cap(u, t, cap[(u, t)])
                    em = self.edge_map.get((u, t))
                    if em is None:
                        em = self.edge_map[(u, t)] = {}
                    em[w] = em.get(w, 0) + M
            # drop whatever is left of the arcs incident to w
            for x in range(n):
                if x == w:
                    continue
                if cap.get((x, w), 0):
                    cap[(x, w)] = 0
                    if (x, w) in self.arc_of:
                        self.fg.set_cap(self.arc_of[(x, w)], 0)
                if cap.get((w, x), 0):
                    cap[(w, x)] = 0
                    if (w, x) in self.arc_of:
                        self.fg.set_cap(self.arc_of[(w, x)], 0)
        # reduced capacities on participants only
        rcap = {}
        for (u, v), c in cap.items():
            if c > 0 and u in self.pset and v in self.pset and u != v:
                rcap[(u, v)] = c
        return rcap, self.edge_map


# --------------------------------------------------------------------------
# phase 2: weighted branching packing on the reduced digraph
# --------------------------------------------------------------------------
class BranchingPacker:
    def __init__(self, parts, rcap, rdem):
        self.parts = sorted(parts)
        self.idx = {v: i for i, v in enumerate(self.parts)}
        self.n = len(self.parts)
        self.rcap = dict(rcap)
        self.rdem = dict(rdem)
        self.fg = FlowGraph(self.n)
        self.arc_of = {}
        for (a, b), c in self.rcap.items():
            if c > 0:
                self.arc_of[(a, b)] = self.fg.add_arc(self.idx[a], self.idx[b], c)
        # pre-allocated arcs x->u used to model singleton (not yet grown) trees
        self.single_arc = {}
        for x in self.parts:
            for u in self.parts:
                if x != u:
                    self.single_arc[(x, u)] = self.fg.add_arc(self.idx[x], self.idx[u], 0)
        self.trees = {}          # tid -> dict
        self.next_tid = 0
        self.temp_arcs = {}      # (x,tid) -> arc id
        self.single = {}         # root -> total weight of singleton trees
        for v in self.parts:
            if self.rdem.get(v, 0) > 0:
                self._new_tree(v, self.rdem[v], {v}, [])

    def _new_tree(self, root, w, R, edges):
        tid = self.next_tid
        self.next_tid += 1
        snode = None
        if len(R) > 1:
            snode = self.fg.add_node()
            for v in R:
                self.fg.add_arc(snode, self.idx[v], INF)
        self.trees[tid] = {'root': root, 'w': w, 'R': set(R),
                           'edges': list(edges), 'snode': snode}
        if snode is None:
            self.single[root] = self.single.get(root, 0) + w
        return tid

    def _drop_tree(self, tid):
        T = self.trees[tid]
        if T['snode'] is None:
            self.single[T['root']] -= T['w']
        else:
            # disable its s_node arcs
            sn = T['snode']
            for i in self.fg.adj[sn]:
                self.fg.set_cap(i, 0)
            for x in self.parts:
                a = self.temp_arcs.get((x, tid))
                if a is not None:
                    self.fg.set_cap(a, 0)
        del self.trees[tid]

    def _temp_arc(self, x, tid):
        a = self.temp_arcs.get((x, tid))
        if a is None:
            T = self.trees[tid]
            a = self.fg.add_arc(self.idx[x], T['snode'], 0)
            self.temp_arcs[(x, tid)] = a
        return a

    def test_edge(self, tid, x, y):
        T = self.trees[tid]
        fg = self.fg
        ix = self.idx[x]
        c_sum = 0
        touched = []
        # singleton trees: aggregate into direct arcs x->u
        for u, w in self.single.items():
            if w <= 0:
                continue
            if T['snode'] is None and T['root'] == u:
                w -= T['w']
                if w <= 0:
                    continue
            a = self.single_arc.get((x, u))
            if a is None:
                continue
            fg.set_cap(a, w)
            touched.append(a)
            c_sum += w
        # grown trees: temp arcs into their s_node
        for oid, O in self.trees.items():
            if oid == tid or O['snode'] is None:
                continue
            a = self._temp_arc(x, oid)
            fg.set_cap(a, O['w'])
            touched.append(a)
            c_sum += O['w']
        cap_xy = self.rcap.get((x, y), 0)
        if cap_xy <= 0:
            for a in touched:
                fg.set_cap(a, 0)
            return 0
        val = fg.maxflow(ix, self.idx[y])
        for a in touched:
            fg.set_cap(a, 0)
        chunks = val - c_sum
        if chunks > T['w']:
            chunks = T['w']
        if chunks > cap_xy:
            chunks = cap_xy
        return chunks if chunks > 0 else 0

    def generate(self):
        parts = self.parts
        nparts = len(parts)
        queue = sorted(self.trees.keys())
        done = []
        guard = 0
        while queue:
            guard += 1
            if guard > 200000:
                raise RuntimeError('branching packer did not converge')
            tid = queue.pop(0)
            T = self.trees.get(tid)
            if T is None:
                continue
            bfs = list(T['R'])
            head = 0
            while head < len(bfs):
                x = bfs[head]
                head += 1
                cands = []
                for (a, b), c in self.rcap.items():
                    if a == x and c > 0 and b not in T['R']:
                        cands.append((-c, b))
                cands.sort()
                for _negc, y in cands:
                    if y in T['R']:
                        continue
                    if self.rcap.get((x, y), 0) <= 0:
                        continue
                    chunks = self.test_edge(tid, x, y)
                    if chunks <= 0:
                        continue
                    bfs.append(y)
                    if chunks < T['w']:
                        ntid = self._new_tree(T['root'], T['w'] - chunks, T['R'], T['edges'])
                        queue.append(ntid)
                        if T['snode'] is None:
                            self.single[T['root']] -= T['w']
                        T['w'] = chunks
                        if T['snode'] is None:
                            self.single[T['root']] += chunks
                    T['edges'].append((x, y))
                    T['R'].add(y)
                    if T['snode'] is not None:
                        self.fg.add_arc(T['snode'], self.idx[y], INF)
                    a = self.arc_of.get((x, y))
                    self.rcap[(x, y)] -= chunks
                    if a is not None:
                        self.fg.set_cap(a, self.rcap[(x, y)])
                    if self.rcap[(x, y)] <= 0:
                        del self.rcap[(x, y)]
            if len(T['R']) != nparts:
                raise RuntimeError('branching incomplete for root %r' % (T['root'],))
            done.append((T['root'], T['w'], list(T['edges'])))
            self._drop_tree(tid)
        return done


# --------------------------------------------------------------------------
# phase 3: expand reduced arcs back to physical walks and emit the plan
# --------------------------------------------------------------------------
def _match(ls1, vs1, ls2, vs2):
    vs1 = list(vs1)
    vs2 = list(vs2)
    res_l = []
    res_v = []
    i = j = 0
    while i < len(ls1):
        v = vs1[i] if vs1[i] < vs2[j] else vs2[j]
        res_l.append(ls1[i] + ls2[j])
        res_v.append(v)
        vs1[i] -= v
        vs2[j] -= v
        if vs1[i] == 0:
            i += 1
        if vs2[j] == 0:
            j += 1
    return res_l, res_v


def flatten(edge_map, u, t, c):
    """Return (paths, counts) with sum(counts)==c for logical arc (u,t)."""
    if (u, t) not in edge_map:
        return [[(u, t)], [c]]
    res_paths = []
    res_cs = []
    entries = sorted(edge_map[u, t].items(), key=lambda e: e[1])
    for w, cp in entries:
        if c <= 0:
            break
        if c >= cp:
            del edge_map[u, t][w]
            take = cp
        else:
            edge_map[u, t][w] = cp - c
            take = c
        p1, c1 = flatten(edge_map, u, w, take)
        p2, c2 = flatten(edge_map, w, t, take)
        pp, cc = _match(p1, c1, p2, c2)
        res_paths.extend(pp)
        res_cs.extend(cc)
        c -= take
    if c > 0:
        res_paths.append([(u, t)])
        res_cs.append(c)
    order = sorted(range(len(res_cs)), key=lambda i: -res_cs[i])
    res_paths = [res_paths[i] for i in order]
    res_cs = [res_cs[i] for i in order]
    return res_paths, res_cs


class RecipeBuilder:
    def __init__(self, link_of):
        self.nodes = []
        self.leaf = {}
        self.cat = {}
        self.link_of = link_of      # (u,v) -> (link_id, direction)

    def leaf_id(self, uv):
        lid = self.leaf.get(uv)
        if lid is None:
            l, d = self.link_of[uv]
            lid = len(self.nodes)
            self.nodes.append([0, l, d])
            self.leaf[uv] = lid
        return lid

    def cat_id(self, a, b):
        k = (a, b)
        lid = self.cat.get(k)
        if lid is None:
            lid = len(self.nodes)
            self.nodes.append([1, a, b])
            self.cat[k] = lid
        return lid

    def path_id(self, arcs):
        cur = None
        for uv in arcs:
            lid = self.leaf_id(uv)
            cur = lid if cur is None else self.cat_id(cur, lid)
        return cur


def compile_plan(n, links, link_caps, parts, rdem):
    """links: list of (u,v); link_caps: list of per-direction capacities."""
    link_of = {}
    cap = {}
    for lid, (u, v) in enumerate(links):
        if u == v:
            continue
        c = link_caps[lid]
        link_of[(u, v)] = (lid, 0)
        link_of[(v, u)] = (lid, 1)
        cap[(u, v)] = cap.get((u, v), 0) + c
        cap[(v, u)] = cap.get((v, u), 0) + c
    total = 0
    for v in parts:
        total += rdem[v]
    cut = deficient_cut(n, cap, parts, rdem, total)
    if cut is not None:
        return ('cut', cut)
    se = SwitchEliminator(n, dict(cap), parts, rdem, total)
    rcap, edge_map = se.run()
    # verify reduced problem still feasible
    cut2 = deficient_cut(n, rcap, parts, rdem, total)
    if cut2 is not None:
        raise RuntimeError('reduced graph lost feasibility')
    trees = BranchingPacker(parts, rcap, rdem).generate()
    # logical load per ordered participant pair
    load = {}
    for root, w, edges in trees:
        for e in edges:
            load[e] = load.get(e, 0) + w
    rb = RecipeBuilder(link_of)
    routes = []
    for (a, b), need in sorted(load.items()):
        paths, counts = flatten(edge_map, a, b, need)
        merged = {}
        order = []
        left = need
        for p, c in zip(paths, counts):
            if left <= 0:
                break
            if c > left:
                c = left
            key = tuple(p)
            if key not in merged:
                merged[key] = 0
                order.append(key)
            merged[key] += c
            left -= c
        if left != 0:
            raise RuntimeError('route capacity shortfall')
        for key in order:
            c = merged[key]
            if c <= 0:
                continue
            rid = rb.path_id(list(key))
            routes.append([a, b, c, rid])
    out_trees = []
    for root, w, edges in trees:
        out_trees.append([root, w, [[a, b] for (a, b) in edges]])
    return ('plan', {'trees': out_trees, 'routes': routes, 'recipes': rb.nodes})
